// Pronoun counts for the We-We Calculator. No DOM, so it can be tested.

export const BRAND_WORDS = new Set(['we', 'us', 'our', 'ours', 'ourselves', 'i', 'me', 'my', 'mine', 'myself']);
export const CUSTOMER_WORDS = new Set(['you', 'your', 'yours', 'yourself', 'yourselves']);

/** Counts brand and reader pronouns. Contractions count by their pronoun ("we're" is "we"). */
export function countPronouns(text) {
  const tokens = text.toLowerCase().replace(/[’]/g, "'").match(/[a-z]+/g) ?? [];
  let brand = 0, customer = 0;
  for (const w of tokens) {
    if (BRAND_WORDS.has(w)) brand++;
    else if (CUSTOMER_WORDS.has(w)) customer++;
  }
  const total = brand + customer;
  return {
    brand,
    customer,
    total,
    brandPct: total ? Math.round((brand / total) * 100) : 0,
    customerPct: total ? 100 - Math.round((brand / total) * 100) : 0,
  };
}
